4	import { openCurrentAnchorTrust } from "./anchor-trust-singleton.js";
5	import { openCreatorSuccessorTrust } from "./creator-close.js";
6	import type { CurrentAnchorTrust } from "./index.js";
7	import {
8		mintCreatorAnchorTrustCheckpointPredecessor,
9		resolveCreatorAnchorTrustMaterial,
10	} from "./internal/seal-authority-custody.js";
