313	function sameBytes(left: Uint8Array, right: Uint8Array): boolean {
314		return compareBytes(left, right) === 0;
315	}
316	
317	function hexBytes(value: string): Uint8Array {
318		return Uint8Array.from(value.match(/../gu) ?? [], (part) => Number.parseInt(part, 16));
319	}

1	import { compareBytes, decodeCanonical, encodeCanonical } from "@ts-drp/canonical";
2	import type { GenerationRef } from "@ts-drp/storage";
3	
4	import { type DetachedClosureCandidate, inspectTrustClosure } from "./anchor-trust.js";
5	import {
6		type CreatorTrustAdvanceRejection,
7		type CreatorTrustAdvanceResult,
8		type DetachedTrustClosure,
9		inspectCreatorTrustAdvance,
10	} from "./creator-trust-advance.js";
11	
12	const DIGEST_HEX = /^[0-9a-f]{64}$/u;
13	const INPUT_KEYS = Object.freeze([
14		"current",
15		"proofRefs",
16		"proposed",
17		"retiringPredecessorAclRef",
18		"retiringProofRefs",
19	]);
20	
21	export type BoundedCreatorTrustAdvanceRejection =
22		| CreatorTrustAdvanceRejection
23		| "RETIRING_PREDECESSOR_ACL_INVALID"
24		| "RETIRING_PROOF_REFS_INVALID";
25	
26	export type BoundedCreatorTrustAdvanceResult =
27		| Readonly<{ readonly kind: "successor"; readonly ok: true }>
28		| Readonly<{ readonly ok: false; readonly reason: BoundedCreatorTrustAdvanceRejection }>;
29	
30	export interface InspectBoundedCreatorTrustAdvanceInput {
31		readonly current: DetachedTrustClosure;
32		readonly proofRefs: readonly GenerationRef[];
33		readonly proposed: DetachedTrustClosure;
34		readonly retiringPredecessorAclRef: GenerationRef;
35		readonly retiringProofRefs: readonly GenerationRef[];
36	}
37	
38	function rejected(reason: BoundedCreatorTrustAdvanceRejection): BoundedCreatorTrustAdvanceResult {
39		return Object.freeze({ ok: false as const, reason });
40	}
41	
42	function plainRecord(value: unknown): value is Readonly<Record<string, unknown>> {
43		if (value === null || typeof value !== "object" || Array.isArray(value)) return false;
44		const prototype = Object.getPrototypeOf(value);
45		return prototype === Object.prototype || prototype === null;
46	}
47	
48	function exactKeys(value: Readonly<Record<string, unknown>>, keys: readonly string[]): boolean {
49		const actual = Reflect.ownKeys(value);
50		return (
51			actual.length === keys.length &&
52			actual.every((key) => typeof key === "string" && keys.includes(key)) &&
53			keys.every((key) => {
54				const descriptor = Object.getOwnPropertyDescriptor(value, key);
55				return descriptor?.enumerable === true && "value" in descriptor;
56			})
57		);
58	}
59	
60	function copyRef(value: unknown): GenerationRef | undefined {
61		if (!plainRecord(value) || !exactKeys(value, ["byteLength", "digest"])) return undefined;
62		if (
63			typeof value.byteLength !== "number" ||
64			!Number.isSafeInteger(value.byteLength) ||
65			value.byteLength < 0 ||
66			typeof value.digest !== "string" ||
67			!DIGEST_HEX.test(value.digest)
68		) {
69			return undefined;
70		}
71		return Object.freeze({ byteLength: value.byteLength, digest: value.digest }) as GenerationRef;
72	}
73	
74	function copyPair(value: unknown): readonly [GenerationRef, GenerationRef] | undefined {
75		if (!Array.isArray(value) || value.length !== 2) return undefined;
76		const first = copyRef(value[0]);
77		const second = copyRef(value[1]);
78		if (first === undefined || second === undefined || first.digest === second.digest) return undefined;
79		return Object.freeze([first, second]);
80	}
81	
82	function sameRef(left: GenerationRef, right: GenerationRef): boolean {
83		return left.byteLength === right.byteLength && left.digest === right.digest;
84	}
85	
86	function compareRef(left: GenerationRef, right: GenerationRef): number {
87		return left.digest < right.digest ? -1 : left.digest > right.digest ? 1 : 0;
88	}
89	
90	function candidateFor(
91		candidates: readonly DetachedClosureCandidate[],
92		ref: GenerationRef
93	): DetachedClosureCandidate | undefined {
94		const matches = candidates.filter((candidate) => sameRef(candidate.ref, ref));
95		return matches.length === 1 ? matches[0] : undefined;
96	}
97	
98	function exactRecord(candidate: DetachedClosureCandidate): Readonly<Record<string, unknown>> | undefined {
99		try {
100			const decoded = decodeCanonical(candidate.bytes);
101			if (!plainRecord(decoded) || compareBytes(encodeCanonical(decoded), candidate.bytes) !== 0) return undefined;
102			return decoded;
103		} catch {
104			return undefined;
105		}
106	}
107	
108	function exactClosure(left: readonly GenerationRef[], right: readonly GenerationRef[]): boolean {
109		if (left.length !== right.length) return false;
110		const sortedLeft = [...left].sort(compareRef);
111		const sortedRight = [...right].sort(compareRef);
112		return sortedLeft.every((ref, index) => sameRef(ref, sortedRight[index] as GenerationRef));
113	}
114	
115	function trustIdentity(
116		bytes: Uint8Array
117	): Readonly<{ readonly currentEpoch: number; readonly objectId: string }> | undefined {
118		try {
119			const decoded = decodeCanonical(bytes);
120			return plainRecord(decoded) &&
121				typeof decoded.currentEpoch === "number" &&
122				Number.isSafeInteger(decoded.currentEpoch) &&
123				decoded.currentEpoch >= 1 &&
124				typeof decoded.objectId === "string"
125				? Object.freeze({ currentEpoch: decoded.currentEpoch, objectId: decoded.objectId })
126				: undefined;
127		} catch {
128			return undefined;
129		}
130	}
