132	/**
133	 * Classifies one bounded creator-trust checkpoint advance without writing storage.
134	 * @param input - Current/proposed closures, the new Cut/QC, and exact stale proof/ACL refs to retire.
135	 * @returns The existing successor verdict or a frozen retirement rejection.
136	 */
137	export function inspectBoundedCreatorTrustAdvance(input: unknown): BoundedCreatorTrustAdvanceResult {
138		try {
139			if (!plainRecord(input) || !exactKeys(input, INPUT_KEYS)) return rejected("TRUST_CLOSURE_INVALID");
140			const typed = input as unknown as InspectBoundedCreatorTrustAdvanceInput;
141			const current = inspectTrustClosure(typed.current);
142			const proposed = inspectTrustClosure(typed.proposed);
143			const proofRefs = copyPair(typed.proofRefs);
144			const retiringProofRefs = copyPair(typed.retiringProofRefs);
145			const retiringAclRef = copyRef(typed.retiringPredecessorAclRef);
146			if (!current.ok || !proposed.ok || proofRefs === undefined) return rejected("TRUST_CLOSURE_INVALID");
147			if (retiringProofRefs === undefined) return rejected("RETIRING_PROOF_REFS_INVALID");
148			if (retiringAclRef === undefined) return rejected("RETIRING_PREDECESSOR_ACL_INVALID");
149			const identity = trustIdentity(current.exactCanonicalTrustStateRecordBytes);
150			if (identity === undefined) return rejected("TRUST_CLOSURE_INVALID");
151			const [retiringCutRef, retiringQcRef] = retiringProofRefs;
152			const [newCutRef, newQcRef] = proofRefs;
153			const retiringCut = candidateFor(typed.current.candidates, retiringCutRef);
154			const retiringQc = candidateFor(typed.current.candidates, retiringQcRef);
155			const retiringAcl = candidateFor(typed.current.candidates, retiringAclRef);
156			const newCut = candidateFor(typed.proposed.candidates, newCutRef);
157			const newQc = candidateFor(typed.proposed.candidates, newQcRef);
158			const retiringCutRecord = retiringCut === undefined ? undefined : exactRecord(retiringCut);
159			const retiringQcRecord = retiringQc === undefined ? undefined : exactRecord(retiringQc);
160			const retiringAclRecord = retiringAcl === undefined ? undefined : exactRecord(retiringAcl);
161			const newCutRecord = newCut === undefined ? undefined : exactRecord(newCut);
162			const newQcRecord = newQc === undefined ? undefined : exactRecord(newQc);
163			if (
164				retiringCut === undefined ||
165				retiringQc === undefined ||
166				retiringCutRecord?.kind !== "drp-hard-epoch-cut" ||
167				retiringCutRecord.objectId !== identity.objectId ||
168				retiringCutRecord.epoch !== identity.currentEpoch - 1 ||
169				retiringQcRecord?.kind !== "drp-seal-qc" ||
170				retiringQcRecord.objectId !== identity.objectId ||
171				retiringQcRecord.epoch !== identity.currentEpoch - 1 ||
172				retiringQcRecord.phase !== "commit"
173			) {
174				return rejected("RETIRING_PROOF_REFS_INVALID");
175			}
176			if (
177				retiringAcl === undefined ||
178				retiringAclRecord?.kind !== "drp-v3-latched-acl" ||
179				retiringAclRecord.objectId !== identity.objectId ||
180				retiringAclRecord.epoch !== identity.currentEpoch - 1
181			) {
182				return rejected("RETIRING_PREDECESSOR_ACL_INVALID");
183			}
184			if (
185				newCut === undefined ||
186				newQc === undefined ||
187				newCutRecord?.kind !== "drp-hard-epoch-cut" ||
188				newCutRecord.objectId !== identity.objectId ||
189				newCutRecord.epoch !== identity.currentEpoch ||
190				newQcRecord?.kind !== "drp-seal-qc" ||
191				newQcRecord.objectId !== identity.objectId ||
192				newQcRecord.epoch !== identity.currentEpoch ||
193				newQcRecord.phase !== "commit"
194			) {
195				return rejected("TRUST_CLOSURE_INVALID");
196			}
197			const retiring = new Set([retiringCutRef.digest, retiringQcRef.digest, retiringAclRef.digest]);
198			if (
199				retiring.has(current.trustRef.digest) ||
200				retiring.size !== 3 ||
201				typed.proposed.closure.some((ref) => retiring.has(ref.digest))
202			) {
203				return rejected("TRUST_CLOSURE_INVALID");
204			}
205			const retained = typed.current.closure.filter(
206				(ref) => ref.digest !== current.trustRef.digest && !retiring.has(ref.digest)
207			);
208			if (retained.length !== typed.current.closure.length - 4) return rejected("TRUST_CLOSURE_INVALID");
209			const expected = [...retained, proposed.trustRef, newCutRef, newQcRef];
210			if (
211				new Set(expected.map((ref) => ref.digest)).size !== expected.length ||
212				!exactClosure(expected, typed.proposed.closure)
213			) {
214				return rejected("TRUST_CLOSURE_INVALID");
215			}
216			const syntheticClosure = Object.freeze(
217				[...typed.proposed.closure, retiringCutRef, retiringQcRef, retiringAclRef].sort(compareRef)
218			);
219			const syntheticCandidates = Object.freeze([...typed.proposed.candidates, retiringCut, retiringQc, retiringAcl]);
220			return inspectCreatorTrustAdvance({
221				current: typed.current,
222				proofRefs,
223				proposed: { candidates: syntheticCandidates, closure: syntheticClosure },
224			}) as CreatorTrustAdvanceResult;
225		} catch {
226			return rejected("TRUST_CLOSURE_INVALID");
227		}
228	}

