17	}
18	
19	export type InspectCreatorTransitionAdvanceResult =
20		| Readonly<{ readonly ok: false; readonly reason: string }>
21		| Readonly<{
22				readonly kind: "successor";
23				readonly ok: true;
24				readonly proposed: CreatorTransitionClosure;
25		  }>;
26	
27	function record(candidate: DetachedClosureCandidate): Readonly<Record<string, unknown>> | undefined {
28		try {
29			const decoded = decodeCanonical(candidate.bytes);
30			return decoded !== null && typeof decoded === "object" && !Array.isArray(decoded)
31				? (decoded as Readonly<Record<string, unknown>>)
32				: undefined;
33		} catch {
34			return undefined;
35		}
36	}
37	
38	function compareRef(left: GenerationRef, right: GenerationRef): number {
39		return left.digest < right.digest ? -1 : left.digest > right.digest ? 1 : 0;
40	}
41	
42	function uniqueCandidate(
43		candidates: readonly DetachedClosureCandidate[],
44		kind: string,
45		epoch: number,
46		phase?: string
47	): DetachedClosureCandidate | undefined {
48		const matches = candidates.filter((candidate) => {
49			const decoded = record(candidate);
50			return (
51				decoded?.kind === kind &&
52				(decoded.kind === "drp-anchor-trust-state" ? decoded.currentEpoch : decoded.epoch) === epoch &&
53				(phase === undefined || decoded.phase === phase)
54			);
55		});
56		return matches.length === 1 ? matches[0] : undefined;
57	}
58	
59	function failure(reason: string): InspectCreatorTransitionAdvanceResult {
60		return Object.freeze({ ok: false as const, reason });
61	}
62	
63	/**
64	 * Selects the compatibility or bounded transition predicate and owns stale-ref derivation.
65	 * @param input - Current/proposed closure pair, new proof refs, and staging/verification mode.
66	 * @returns The authenticated proposal (normalized only for in-memory staging) or a rejection.
67	 */
68	export function inspectCreatorTransitionAdvance(
69		input: InspectCreatorTransitionAdvanceInput
70	): InspectCreatorTransitionAdvanceResult {
71		try {
72			const trustCandidates = input.current.candidates.filter(
73				(candidate) => record(candidate)?.kind === "drp-anchor-trust-state"
74			);
75			if (trustCandidates.length !== 1) return failure("TRUST_CLOSURE_INVALID");
76			const trust = record(trustCandidates[0] as DetachedClosureCandidate);
77			if (typeof trust?.currentEpoch !== "number" || !Number.isSafeInteger(trust.currentEpoch)) {
78				return failure("TRUST_CLOSURE_INVALID");
79			}
80			if (trust.currentEpoch === 0) {
81				const result = inspectCreatorTrustAdvance(input);
82				return result.ok
83					? Object.freeze({ kind: result.kind, ok: true as const, proposed: input.proposed })
84					: failure(result.reason);
85			}
86			const retiringEpoch = trust.currentEpoch - 1;
87			const retiringCut = uniqueCandidate(input.current.candidates, "drp-hard-epoch-cut", retiringEpoch);
88			const retiringQc = uniqueCandidate(input.current.candidates, "drp-seal-qc", retiringEpoch, "commit");
89			const retiringAcl = uniqueCandidate(input.current.candidates, "drp-v3-latched-acl", retiringEpoch);
90			if (retiringCut === undefined || retiringQc === undefined || retiringAcl === undefined) {
91				return failure("RETIRING_PROOF_REFS_INVALID");
92			}
93			const retiring = new Set([retiringCut.ref.digest, retiringQc.ref.digest, retiringAcl.ref.digest]);
94			const proposed =
95				input.mode === "stage"
96					? Object.freeze({
97							candidates: Object.freeze(
98								input.proposed.candidates.filter((candidate) => !retiring.has(candidate.ref.digest))
99							),
100							closure: Object.freeze(input.proposed.closure.filter((ref) => !retiring.has(ref.digest)).sort(compareRef)),
101						})
102					: input.proposed;
103			const result = inspectBoundedCreatorTrustAdvance({
104				current: input.current,
105				proofRefs: input.proofRefs,
106				proposed,
107				retiringPredecessorAclRef: retiringAcl.ref,
108				retiringProofRefs: [retiringCut.ref, retiringQc.ref],
109			});
110			return result.ok ? Object.freeze({ kind: result.kind, ok: true as const, proposed }) : failure(result.reason);
111		} catch {
112			return failure("TRUST_CLOSURE_INVALID");
113		}
114	}

